def D(n):
    return n**3 + 4*n**2 + 6*n + 4

def is_2_5_power(num):
    if num <= 0:
        return False
    while num % 2 == 0:
        num //= 2
    while num % 5 == 0:
        num //= 5
    return num == 1

def check_divisibility(n, d_n):
    # Check if 20^(n+1) is divisible by D(n)
    # Since 20 = 2^2 * 5, we need D(n) to only have prime factors 2 and 5
    # This is already checked by is_2_5_power, but we check the exponents for rigor.

    # Calculate the actual power of 2 and 5 in D(n)
    temp_d = d_n
    count_2 = 0
    while temp_d > 0 and temp_d % 2 == 0:
        count_2 += 1
        temp_d //= 2

    count_5 = 0
    while temp_d > 0 and temp_d % 5 == 0:
        count_5 += 1
        temp_d //= 5

    # The max power of 2 in 20^(n+1) is 2*(n+1)
    max_exp_2 = 2 * (n + 1)
    # The max power of 5 in 20^(n+1) is (n+1)
    max_exp_5 = n + 1

    if temp_d != 1:
        # Should not happen if is_2_5_power passed, but for safety
        return False

    return count_2 <= max_exp_2 and count_5 <= max_exp_5

solutions = []
for n in range(21):
    d_n = D(n)
    if is_2_5_power(d_n):
        if check_divisibility(n, d_n):
            solutions.append(n)

print("Found solutions (n <= 20 where D(n) is 2^a 5^b and divisibility holds):")
print(solutions)
